import { readFileSync } from 'node:fs';
let s = readFileSync(0, 'utf8');
// escape all non-ASCII and control chars so nothing is invisible
s = s.replace(/[^\n\x20-\x7e]/g, c => '<U+' + c.codePointAt(0).toString(16).toUpperCase().padStart(4, '0') + '>');
process.stdout.write(s);

import { writeFileSync } from 'node:fs';
const cases = [
  // tables vs header precedence
  "# h|x\n-|-",
  "h|x\n-|-",
  "a|b\n---",
  "a|b\n-|-",
  "|a|b|\n|-|-|",
  "# a|b\n|-|-|",
  "a|b\n===",
  "\n---\n-|-",
  "***\n-|-",
  // code block blank-line continuation (EmptyBlockProcessor filler)
  "    a\n\n    b",
  "    a\n\n\n    b",
  "    a\n\n\n\n    b",
  "    a\n      \n    b",
  // attr_list attribute ordering on headers
  "# h {: #i .c k=v }",
  "# h {: .c #i }",
  "# h {: k=v #i .c1 .c2 }",
  "# h {: k=\"a b\" }",
  // header + hr adjacency again
  "# a\n---\n# b",
  "# a\n===\n# b",
  // paragraph lstrip with newline
  "\n\n\n   x",
  "\n   x",
  // blocks that begin with newline (EmptyBlockProcessor)
  "a\n\n\n# h",
  "a\n\n\n---",
  "a\n\n\n> q",
  // trailing hash edge: header text ending in escaped backslash-hash
  "# h \\#\\#",
  "# h \\###",
  "# h #\\#",
  // hr made of exactly 3 chars with max gaps
  "\n-  -  -  ",
  "*  *  *  ",
  "_  _  _  ",
  // hr with leading 1-3 spaces and interior gaps
  "   *  *  *",
  "    *  *  *",
  "  - - -",
  // header inside blockquote with trailing hashes
  "> ## h ##",
  "> h\n> ---",
  // multiline setext blocks re-entering
  "a\n---\nb\n---\nc\n---",
  "a\n===\n---",
  "a\n---\n===",
  // consecutive different constructs, no blank lines
  "# h\na\n===\n***\nb\n---\nc",
  // paragraphs with only punctuation
  ".",
  "..",
  "...",
  ":",
  "::",
  // header with tab only after hashes
  "###\t",
  "###\tx",
  "###\t\tx",
  // trailing spaces then EOF in header
  "###### h6      ",
  // hr with tab in it
  "*\t*\t*",
  "***\t***",
  // final sanity: full document
  "Title\n=====\n\nIntro paragraph with a line break here.  \nSecond line.\n\nSub\n---\n\n### ATX ###\n\n* * *\n\nlast",
];
writeFileSync('/tmp/pb/b11.json', JSON.stringify(cases, null, 1));
console.log(cases.length);
